const raw = $input.first()?.json || {};
// Handle both webhook POST payload (raw.body) and direct item payload (raw)
const tender = (raw.body && typeof raw.body === 'object' && Object.keys(raw.body).length > 0) ? raw.body : raw;

// Build targeted search queries
const buyer = tender.buyer || tender.buyer_name || 'Ministère de la Santé';
const buyerQuery = `"${buyer}" Tunisia IT projects technology budget`;
const sectorQuery = `"${buyer}" digital transformation software`;

return [{
  json: {
    tender_id: tender.id || tender.tender_id || '',
    buyer: buyer,
    country: tender.country || 'Tunisia',
    description: tender.description || '',
    source: tender.source || '',
    url: tender.url || '',
    published_date: tender.published_date || '',
    deadline: tender.deadline || '',
    search_query_1: buyerQuery,
    search_query_2: sectorQuery
  }
}];

// 1. Retrieve original tender data from Node 2
const tender = $('Code in JavaScript').first()?.json || {};

// 2. Retrieve Serper Query 1 results (from Node 3)
const serper1 = $('HTTP Request - Serper 1').first()?.json || {};
const organic1 = serper1.organic || [];

// 3. Retrieve Serper Query 2 results (from Node 4 / current input)
const serper2 = $input.first()?.json || $('HTTP Request - Serper 2').first()?.json || {};
const organic2 = serper2.organic || [];

// 4. Helper to format search results
const formatResults = (items, label) => {
  if (!Array.isArray(items) || items.length === 0) {
    return `[No organic search results found for: ${label}]`;
  }
  return items.slice(0, 5).map((item, idx) => {
    const title = item.title || 'Untitled';
    const snippet = item.snippet || 'No snippet available';
    const link = item.link || '';
    return `${idx + 1}. ${title}\nSnippet: ${snippet}\nSource: ${link}`;
  }).join('\n\n');
};

const text1 = formatResults(organic1, tender.search_query_1 || 'Buyer query');
const text2 = formatResults(organic2, tender.search_query_2 || 'Sector query');

const combinedText = `=== SEARCH RESULTS: BUYER IT PROJECTS & BUDGET ===\n${text1}\n\n=== SEARCH RESULTS: DIGITAL TRANSFORMATION & SOFTWARE ===\n${text2}`;

return [{
  json: {
    tender_id: tender.tender_id || '',
    buyer: tender.buyer || 'Unknown',
    country: tender.country || '',
    description: tender.description || '',
    source: tender.source || '',
    url: tender.url || '',
    published_date: tender.published_date || '',
    deadline: tender.deadline || '',
    search_results_text: combinedText
  }
}];

